/*
 * THE STARTER PAGE
 * ================
 * A complete, real page that the builder can open, edit and extend.
 *
 * It is a multi-section Arabic platform: RTL layout, Tailwind from a CDN,
 * web fonts, an icon font, a dark theme, tabs, a digital tasbih, qibla and
 * prayer times, mushaf paging with bookmarks, a surah explorer and a hadith
 * search. Every one of those exercises a different part of the builder, so
 * the starter is also the builder's own integration test: if the import,
 * the page stylesheet or the export ever breaks, it shows here first.
 *
 * The behaviour that is not plain markup (the counters, the player, the
 * search) lives in starters/nur-runtime.js and is attached as the document
 * script, so the exported page is interactive and not a screenshot.
 *
 * Kept as a quoted string: the page contains backticks and ${...}.
 */

export const NUR_FULL_HTML = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\" class=\"dark\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>نور - المنصة الإسلامية الشاملة</title>\n    \n    <!-- Tailwind CSS CDN -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <script>\n        tailwind.config = {\n            darkMode: 'class',\n            theme: {\n                extend: {\n                    colors: {\n                        emerald: {\n                            50: '#ecfdf5',\n                            100: '#d1fae5',\n                            500: '#10b981',\n                            600: '#059669',\n                            700: '#047857',\n                            800: '#065f46',\n                            900: '#064e3b',\n                            950: '#022c22'\n                        },\n                        gold: {\n                            400: '#fbbf24',\n                            500: '#f59e0b',\n                            600: '#d97706',\n                            700: '#b45309'\n                        },\n                        slate: {\n                            850: '#131f33',\n                            900: '#0f172a',\n                            950: '#080d1a'\n                        }\n                    },\n                    fontFamily: {\n                        cairo: ['Cairo', 'sans-serif'],\n                        amiri: ['Amiri', 'serif'],\n                        quran: ['Scheherazade New', 'Amiri', 'serif']\n                    }\n                }\n            }\n        }\n    </script>\n    \n    <!-- Google Fonts for Typography -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Amiri:ital,wght@0,400;0,700;1,400&family=Cairo:wght@300;400;500;600;700;800&family=Scheherazade+New:wght@400;700&display=swap\" rel=\"stylesheet\">\n    \n    <!-- Font Awesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n    \n    <style>\n        /* Custom Scrollbar */\n        ::-webkit-scrollbar {\n            width: 8px;\n            height: 8px;\n        }\n        ::-webkit-scrollbar-track {\n            background: rgba(15, 23, 42, 0.6);\n        }\n        ::-webkit-scrollbar-thumb {\n            background: rgba(16, 185, 129, 0.4);\n            border-radius: 9999px;\n        }\n        ::-webkit-scrollbar-thumb:hover {\n            background: rgba(16, 185, 129, 0.7);\n        }\n\n        /* Glassmorphism Styles */\n        .glass-panel {\n            background: rgba(255, 255, 255, 0.85);\n            backdrop-filter: blur(16px);\n            -webkit-backdrop-filter: blur(16px);\n            border: 1px solid rgba(255, 255, 255, 0.4);\n        }\n        .dark .glass-panel {\n            background: rgba(15, 23, 42, 0.82);\n            backdrop-filter: blur(16px);\n            -webkit-backdrop-filter: blur(16px);\n            border: 1px solid rgba(255, 255, 255, 0.08);\n        }\n\n        .glass-card {\n            background: rgba(255, 255, 255, 0.9);\n            backdrop-filter: blur(12px);\n            border: 1px solid rgba(226, 232, 240, 0.8);\n        }\n        .dark .glass-card {\n            background: rgba(30, 41, 59, 0.7);\n            backdrop-filter: blur(12px);\n            border: 1px solid rgba(255, 255, 255, 0.05);\n        }\n\n        /* Background Pattern */\n        .bg-pattern {\n            background-color: #f8fafc;\n            background-image: radial-gradient(rgba(16, 185, 129, 0.09) 1px, transparent 1px);\n            background-size: 24px 24px;\n        }\n        .dark .bg-pattern {\n            background-color: #080d1a;\n            background-image: radial-gradient(rgba(16, 185, 129, 0.12) 1px, transparent 1px);\n            background-size: 24px 24px;\n        }\n\n        /* Quran Verses & Arabic Text Styling */\n        .font-quran-text {\n            font-family: 'Scheherazade New', 'Amiri', serif;\n            line-height: 2.3;\n            word-spacing: 2px;\n        }\n\n        .font-amiri {\n            font-family: 'Amiri', serif;\n        }\n\n        /* Smooth UI Animations */\n        .tab-transition {\n            transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);\n        }\n\n        /* Pulse highlight for active playback */\n        .verse-playing {\n            border-right: 4px solid #10b981;\n            background: rgba(16, 185, 129, 0.12);\n        }\n    </style>\n</head>\n<body class=\"bg-pattern text-slate-800 dark:text-slate-100 min-h-screen flex flex-col font-cairo selection:bg-emerald-600 selection:text-white\">\n\n    <!-- HEADER / NAVIGATION BAR -->\n    <header class=\"sticky top-0 z-50 glass-panel border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n        <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n            <div class=\"flex items-center justify-between h-20\">\n                \n                <!-- Brand & Title -->\n                <div class=\"flex items-center gap-3 cursor-pointer\" onclick=\"switchTab('moshaf')\">\n                    <div class=\"w-11 h-11 rounded-2xl bg-gradient-to-tr from-emerald-800 via-emerald-600 to-gold-500 flex items-center justify-center text-white shadow-lg shadow-emerald-600/30\">\n                        <i class=\"fa-solid fa-kaaba text-xl\"></i>\n                    </div>\n                    <div>\n                        <div class=\"flex items-center gap-2\">\n                            <span class=\"text-2xl font-black bg-gradient-to-l from-emerald-600 via-emerald-400 to-gold-500 bg-clip-text text-transparent\">نُور</span>\n                            <span class=\"text-xs px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 font-bold\">المنصة الشاملة</span>\n                        </div>\n                        <p class=\"text-[11px] text-slate-500 dark:text-slate-400 font-medium\">المصحف • التلاوة • الحديث • الصلاة • الأذكار</p>\n                    </div>\n                </div>\n\n                <!-- Desktop Navigation Tabs -->\n                <nav class=\"hidden lg:flex items-center gap-1 bg-slate-100 dark:bg-slate-900/90 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800/80 shadow-inner\">\n                    <button onclick=\"switchTab('moshaf')\" id=\"nav-btn-moshaf\" class=\"nav-tab px-4 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 tab-transition text-emerald-600 dark:text-emerald-400 bg-white dark:bg-slate-800 shadow-sm\">\n                        <i class=\"fa-solid fa-book-open text-emerald-500\"></i> المصحف الشريف\n                    </button>\n                    <button onclick=\"switchTab('quran')\" id=\"nav-btn-quran\" class=\"nav-tab px-4 py-2.5 rounded-xl text-sm font-medium flex items-center gap-2 tab-transition text-slate-600 dark:text-slate-300 hover:text-emerald-600 dark:hover:text-emerald-400\">\n                        <i class=\"fa-solid fa-headphones\"></i> تلاوة وسور\n                    </button>\n                    <button onclick=\"switchTab('hadith')\" id=\"nav-btn-hadith\" class=\"nav-tab px-4 py-2.5 rounded-xl text-sm font-medium flex items-center gap-2 tab-transition text-slate-600 dark:text-slate-300 hover:text-emerald-600 dark:hover:text-emerald-400\">\n                        <i class=\"fa-solid fa-scroll\"></i> الأحاديث النبوية\n                    </button>\n                    <button onclick=\"switchTab('prayer')\" id=\"nav-btn-prayer\" class=\"nav-tab px-4 py-2.5 rounded-xl text-sm font-medium flex items-center gap-2 tab-transition text-slate-600 dark:text-slate-300 hover:text-emerald-600 dark:hover:text-emerald-400\">\n                        <i class=\"fa-solid fa-compass\"></i> مواقيت الصلاة\n                    </button>\n                    <button onclick=\"switchTab('tasbih')\" id=\"nav-btn-tasbih\" class=\"nav-tab px-4 py-2.5 rounded-xl text-sm font-medium flex items-center gap-2 tab-transition text-slate-600 dark:text-slate-300 hover:text-emerald-600 dark:hover:text-emerald-400\">\n                        <i class=\"fa-solid fa-hands-praying\"></i> السبحة الإلكترونية\n                    </button>\n                </nav>\n\n                <!-- Actions / Controls -->\n                <div class=\"flex items-center gap-3\">\n                    <!-- Dark Mode Toggle -->\n                    <button onclick=\"toggleTheme()\" class=\"p-3 rounded-2xl bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition shadow-xs\" title=\"تغيير المظهر\">\n                        <i class=\"fa-solid fa-moon text-lg dark:hidden\"></i>\n                        <i class=\"fa-solid fa-sun text-lg hidden dark:block text-gold-400\"></i>\n                    </button>\n                </div>\n            </div>\n        </div>\n\n        <!-- Mobile Bottom Navigation Bar -->\n        <div class=\"lg:hidden fixed bottom-0 left-0 right-0 glass-panel border-t border-slate-200 dark:border-slate-800 z-50 px-2 py-2 shadow-2xl\">\n            <div class=\"grid grid-cols-5 gap-1 text-center\">\n                <button onclick=\"switchTab('moshaf')\" id=\"mob-btn-moshaf\" class=\"mob-tab flex flex-col items-center py-1.5 px-1 rounded-xl text-emerald-500\">\n                    <i class=\"fa-solid fa-book-open text-base\"></i>\n                    <span class=\"text-[10px] font-bold mt-1\">المصحف</span>\n                </button>\n                <button onclick=\"switchTab('quran')\" id=\"mob-btn-quran\" class=\"mob-tab flex flex-col items-center py-1.5 px-1 rounded-xl text-slate-400\">\n                    <i class=\"fa-solid fa-headphones text-base\"></i>\n                    <span class=\"text-[10px] font-medium mt-1\">تلاوة</span>\n                </button>\n                <button onclick=\"switchTab('hadith')\" id=\"mob-btn-hadith\" class=\"mob-tab flex flex-col items-center py-1.5 px-1 rounded-xl text-slate-400\">\n                    <i class=\"fa-solid fa-scroll text-base\"></i>\n                    <span class=\"text-[10px] font-medium mt-1\">الحديث</span>\n                </button>\n                <button onclick=\"switchTab('prayer')\" id=\"mob-btn-prayer\" class=\"mob-tab flex flex-col items-center py-1.5 px-1 rounded-xl text-slate-400\">\n                    <i class=\"fa-solid fa-compass text-base\"></i>\n                    <span class=\"text-[10px] font-medium mt-1\">الصلاة</span>\n                </button>\n                <button onclick=\"switchTab('tasbih')\" id=\"mob-btn-tasbih\" class=\"mob-tab flex flex-col items-center py-1.5 px-1 rounded-xl text-slate-400\">\n                    <i class=\"fa-solid fa-hands-praying text-base\"></i>\n                    <span class=\"text-[10px] font-medium mt-1\">السبحة</span>\n                </button>\n            </div>\n        </div>\n    </header>\n\n    <!-- MAIN APP CONTAINER -->\n    <main class=\"flex-grow max-w-7xl w-full mx-auto px-3 sm:px-6 lg:px-8 py-6 pb-28 lg:pb-12\">\n\n        <!-- Server Status Notification Banner -->\n        <div id=\"server-status-bar\" class=\"mb-5 p-3 rounded-2xl glass-panel border border-emerald-500/20 flex items-center justify-between text-xs sm:text-sm\">\n            <div class=\"flex items-center gap-2\">\n                <span class=\"relative flex h-3 w-3\">\n                    <span id=\"status-ping\" class=\"animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75\"></span>\n                    <span id=\"status-dot\" class=\"relative inline-flex rounded-full h-3 w-3 bg-emerald-500\"></span>\n                </span>\n                <span id=\"status-text\" class=\"font-bold text-slate-700 dark:text-slate-200\">متصل بسيرفرات مصحف المجمع الملكي الملك فهد</span>\n            </div>\n            <div class=\"flex items-center gap-3 text-xs text-slate-500\">\n                <span id=\"server-speed\" class=\"hidden sm:inline-block font-mono bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 px-2 py-0.5 rounded-full\">استجابة فائقة السرعة</span>\n                <button onclick=\"checkServerConnectivity()\" class=\"hover:text-emerald-500 transition\"><i class=\"fa-solid fa-arrows-rotate\"></i> إعادة فحص</button>\n            </div>\n        </div>\n\n        <!-- ================= TAB 1: المصحف الشريف الحقيقي ================= -->\n        <section id=\"tab-sec-moshaf\" class=\"tab-panel block space-y-5\">\n            \n            <!-- Controls & Toolbar Header -->\n            <div class=\"glass-panel rounded-3xl p-4 sm:p-6 shadow-sm border border-emerald-500/20\">\n                <div class=\"flex flex-col lg:flex-row items-center justify-between gap-4\">\n                    \n                    <!-- Direct Navigation Jumpers -->\n                    <div class=\"flex flex-wrap items-center justify-center lg:justify-start gap-2 sm:gap-3 w-full lg:w-auto\">\n                        <!-- Surah Selector -->\n                        <div class=\"flex items-center gap-1.5 bg-white dark:bg-slate-900 px-3 py-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-xs\">\n                            <i class=\"fa-solid fa-list-ol text-emerald-500 text-xs\"></i>\n                            <select id=\"moshaf-surah-select\" onchange=\"jumpToSurah(this.value)\" class=\"bg-transparent text-xs sm:text-sm font-bold focus:outline-none text-slate-800 dark:text-slate-100 cursor-pointer\">\n                                <option value=\"\">اختر السورة...</option>\n                            </select>\n                        </div>\n\n                        <!-- Juz Selector -->\n                        <div class=\"flex items-center gap-1.5 bg-white dark:bg-slate-900 px-3 py-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-xs\">\n                            <i class=\"fa-solid fa-bookmark text-gold-500 text-xs\"></i>\n                            <select id=\"moshaf-juz-select\" onchange=\"jumpToJuz(this.value)\" class=\"bg-transparent text-xs sm:text-sm font-bold focus:outline-none text-slate-800 dark:text-slate-100 cursor-pointer\">\n                                <option value=\"\">اختر الجزء (١-٣٠)...</option>\n                            </select>\n                        </div>\n\n                        <!-- Manual Page Direct Input -->\n                        <div class=\"flex items-center gap-2 bg-white dark:bg-slate-900 px-3 py-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-xs\">\n                            <span class=\"text-xs font-bold text-slate-500\">صفحة</span>\n                            <input type=\"number\" id=\"moshaf-page-input\" min=\"1\" max=\"604\" value=\"1\" onchange=\"jumpToPage(this.value)\" class=\"w-12 text-center text-sm font-extrabold bg-transparent text-emerald-600 dark:text-emerald-400 focus:outline-none\">\n                            <span class=\"text-xs text-slate-400 font-semibold\">من ٦٠٤</span>\n                        </div>\n                    </div>\n\n                    <!-- View Options & Page Controls -->\n                    <div class=\"flex items-center gap-2 flex-wrap justify-center\">\n                        <!-- Play Page Recitation -->\n                        <button onclick=\"playCurrentPageAudio()\" id=\"btn-page-audio\" class=\"px-4 py-2.5 rounded-2xl bg-emerald-600 text-white font-bold text-xs sm:text-sm hover:bg-emerald-700 transition shadow-md flex items-center gap-2\">\n                            <i class=\"fa-solid fa-circle-play text-base\"></i>\n                            <span>استماع للصفحة</span>\n                        </button>\n\n                        <!-- Bookmark Position -->\n                        <button onclick=\"saveMoshafBookmark()\" class=\"px-3 py-2.5 rounded-2xl bg-gold-500/10 text-gold-600 dark:text-gold-400 border border-gold-500/20 font-bold text-xs sm:text-sm hover:bg-gold-500/20 transition flex items-center gap-2\" title=\"حفظ العلامة\">\n                            <i class=\"fa-solid fa-ribbon text-base\"></i>\n                            <span class=\"hidden sm:inline\">حفظ موضع القراءة</span>\n                        </button>\n\n                        <!-- Toggle View Mode (Dual Desktop / Single Mobile) -->\n                        <button onclick=\"toggleDualPageView()\" id=\"btn-dual-mode\" class=\"hidden md:flex px-3 py-2.5 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 font-bold text-xs sm:text-sm hover:border-emerald-500 transition items-center gap-2\">\n                            <i class=\"fa-solid fa-book-open\"></i>\n                            <span id=\"dual-mode-text\">عرض صفحتين</span>\n                        </button>\n\n                        <!-- Fullscreen Stage -->\n                        <button onclick=\"toggleStageFullscreen()\" class=\"p-2.5 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-300 hover:text-emerald-500 transition\" title=\"ملء الشاشة\">\n                            <i class=\"fa-solid fa-expand text-base\"></i>\n                        </button>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Resume Bookmark Banner (Shows if saved page exists) -->\n            <div id=\"resume-bookmark-banner\" class=\"hidden p-4 rounded-3xl bg-gradient-to-r from-emerald-800 via-emerald-700 to-teal-800 text-white shadow-lg flex items-center justify-between\">\n                <div class=\"flex items-center gap-3\">\n                    <div class=\"w-9 h-9 rounded-xl bg-white/20 flex items-center justify-center font-bold\">\n                        <i class=\"fa-solid fa-clock-rotate-left\"></i>\n                    </div>\n                    <div>\n                        <h4 class=\"text-sm font-bold\">آخر موضع قراءة محفوظ</h4>\n                        <p class=\"text-xs opacity-90\">أنت عند الصفحة <span id=\"saved-page-num\" class=\"font-bold underline\">1</span></p>\n                    </div>\n                </div>\n                <button onclick=\"loadSavedBookmarkPage()\" class=\"px-4 py-2 bg-white text-emerald-900 rounded-xl font-bold text-xs hover:bg-emerald-50 transition shadow\">\n                    الانتقال فوراً\n                </button>\n            </div>\n\n            <!-- REAL MOSHAF DISPLAY STAGE -->\n            <div id=\"moshaf-stage\" class=\"glass-panel rounded-3xl p-3 sm:p-8 flex flex-col justify-between items-center min-h-[600px] sm:min-h-[750px] relative shadow-2xl border border-emerald-500/20 bg-amber-50/20 dark:bg-slate-950/40\">\n                \n                <!-- Top Info Bar -->\n                <div class=\"w-full flex items-center justify-between text-xs sm:text-sm font-bold text-slate-600 dark:text-slate-300 border-b border-slate-200/80 dark:border-slate-800/80 pb-3 mb-2 px-2\">\n                    <span id=\"moshaf-surah-title\" class=\"text-emerald-600 dark:text-emerald-400 flex items-center gap-2\">\n                        <i class=\"fa-solid fa-kaaba\"></i> سورة الفاتحة\n                    </span>\n                    <span id=\"moshaf-page-display\" class=\"bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 px-3 py-1 rounded-full border border-emerald-500/20 font-mono\">\n                        صفحة 1\n                    </span>\n                    <span id=\"moshaf-juz-title\">الجزء 1</span>\n                </div>\n\n                <!-- Page Display Container (RTL Reading Order: Right to Left) -->\n                <div class=\"relative w-full flex-grow flex items-center justify-center my-3 gap-4 select-none\" id=\"moshaf-images-wrapper\">\n                    \n                    <!-- BIG RTL NAVIGATION BUTTON (PREVIOUS PAGE / RIGHT SIDE IN ARABIC) -->\n                    <button onclick=\"prevMoshafPage()\" class=\"absolute right-2 sm:right-4 z-30 w-12 h-12 sm:w-14 sm:h-14 rounded-full glass-card hover:bg-emerald-600 hover:text-white text-slate-800 dark:text-slate-100 shadow-2xl flex items-center justify-center transition transform active:scale-90 border border-emerald-500/30\" title=\"الصفحة السابقة\">\n                        <i class=\"fa-solid fa-chevron-right text-xl\"></i>\n                    </button>\n\n                    <!-- Page Container Right (Secondary Page in Dual Mode) -->\n                    <div id=\"moshaf-img-container-left\" class=\"hidden w-1/2 max-w-[480px] aspect-[1/1.45] relative rounded-2xl overflow-hidden shadow-2xl border border-amber-200/60 dark:border-slate-800 bg-amber-50 dark:bg-slate-900\">\n                        <img id=\"moshaf-img-left\" src=\"\" alt=\"صفحة المصحف الشريف\" class=\"w-full h-full object-contain transition-opacity duration-300\">\n                    </div>\n\n                    <!-- Page Container Primary (Center / Right) -->\n                    <div id=\"moshaf-img-container-right\" class=\"w-full max-w-[550px] aspect-[1/1.45] relative rounded-2xl overflow-hidden shadow-2xl border border-amber-200/60 dark:border-slate-800 bg-amber-50 dark:bg-slate-900 flex items-center justify-center\">\n                        \n                        <!-- Loader Overlay -->\n                        <div id=\"moshaf-loader\" class=\"absolute inset-0 flex flex-col items-center justify-center bg-slate-950/40 backdrop-blur-sm z-20\">\n                            <div class=\"w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-3\"></div>\n                            <span class=\"text-xs font-bold text-slate-100 bg-slate-900/80 px-3 py-1 rounded-full border border-slate-700\">جاري تحميل الصفحة من السيرفر...</span>\n                        </div>\n\n                        <!-- Real Page Image -->\n                        <img id=\"moshaf-img-right\" src=\"\" alt=\"صفحة المصحف الشريف\" class=\"w-full h-full object-contain transition-opacity duration-300\">\n                    </div>\n\n                    <!-- BIG RTL NAVIGATION BUTTON (NEXT PAGE / LEFT SIDE IN ARABIC) -->\n                    <button onclick=\"nextMoshafPage()\" class=\"absolute left-2 sm:left-4 z-30 w-12 h-12 sm:w-14 sm:h-14 rounded-full glass-card hover:bg-emerald-600 hover:text-white text-slate-800 dark:text-slate-100 shadow-2xl flex items-center justify-center transition transform active:scale-90 border border-emerald-500/30\" title=\"الصفحة التالية\">\n                        <i class=\"fa-solid fa-chevron-left text-xl\"></i>\n                    </button>\n                </div>\n\n                <!-- Bottom Slider Bar -->\n                <div class=\"w-full max-w-lg mx-auto pt-2\">\n                    <input type=\"range\" id=\"moshaf-slider\" min=\"1\" max=\"604\" value=\"1\" oninput=\"jumpToPage(this.value)\" class=\"w-full accent-emerald-500 cursor-pointer h-2 bg-slate-200 dark:bg-slate-800 rounded-lg\">\n                    <div class=\"flex justify-between text-[11px] font-mono text-slate-400 mt-1\">\n                        <span>الصفحة ١ (الفاتحة)</span>\n                        <span>الصفحة ٦٠٤ (الناس)</span>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- ================= TAB 2: تلاوة وسور ================= -->\n        <section id=\"tab-sec-quran\" class=\"tab-panel hidden space-y-6\">\n            <!-- Search & Reciter Select Header -->\n            <div class=\"glass-panel rounded-3xl p-5 shadow-sm border border-emerald-500/20\">\n                <div class=\"flex flex-col md:flex-row items-center justify-between gap-4\">\n                    <div class=\"relative w-full md:w-96\">\n                        <i class=\"fa-solid fa-magnifying-glass absolute right-4 top-1/2 -translate-y-1/2 text-slate-400\"></i>\n                        <input type=\"text\" id=\"surah-search-input\" onkeyup=\"filterSurahsList()\" placeholder=\"ابحث باسم السورة أو رقمها...\" class=\"w-full pr-11 pl-4 py-3 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 font-medium\">\n                    </div>\n                    <div class=\"flex items-center gap-3 w-full md:w-auto\">\n                        <label class=\"text-xs font-bold text-slate-500 whitespace-nowrap\">القارئ المحبوب:</label>\n                        <select id=\"reciter-select\" class=\"w-full md:w-auto px-4 py-3 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-sm font-bold focus:outline-none focus:ring-2 focus:ring-emerald-500\">\n                            <option value=\"ar.alafasy\">مشاري راشد العفاسي</option>\n                            <option value=\"ar.abdulbasitmurattal\">عبد الباسط عبد الصمد</option>\n                            <option value=\"ar.sudais\">عبد الرحمن السدیس</option>\n                            <option value=\"ar.shaatree\">أبو بكر الشاطري</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Surah Explorer Grid -->\n            <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                <!-- Sidebar Surah List -->\n                <div class=\"lg:col-span-4 max-h-[620px] overflow-y-auto glass-panel rounded-3xl p-3 space-y-2 pr-1\" id=\"surah-list-sidebar\">\n                    <div class=\"text-center py-12 text-slate-400\">\n                        <i class=\"fa-solid fa-spinner fa-spin text-3xl text-emerald-500 mb-2\"></i>\n                        <p class=\"text-xs\">جاري تحميل قائمة السور...</p>\n                    </div>\n                </div>\n\n                <!-- Verse View Stage -->\n                <div class=\"lg:col-span-8 glass-panel rounded-3xl p-6 relative flex flex-col justify-between min-h-[500px]\" id=\"surah-reading-stage\">\n                    <div id=\"active-surah-header\" class=\"hidden mb-6 p-6 rounded-3xl bg-gradient-to-r from-emerald-900 via-emerald-800 to-teal-900 text-white text-center shadow-lg relative overflow-hidden\">\n                        <h2 id=\"active-surah-ar-name\" class=\"font-quran-text text-4xl mb-2 text-gold-400\">الفاتحة</h2>\n                        <p id=\"active-surah-sub\" class=\"text-sm opacity-90\">مكية • عدد آياتها ٧</p>\n                        <div class=\"mt-4 font-quran-text text-2xl text-amber-200\">\n                            بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n                        </div>\n                    </div>\n\n                    <div id=\"verses-list-container\" class=\"space-y-6\">\n                        <div class=\"text-center py-24 text-slate-400\">\n                            <i class=\"fa-solid fa-book-open text-5xl text-emerald-500/30 mb-3\"></i>\n                            <p class=\"text-base font-bold\">اختر سورة من القائمة للبدء في القراءة والاستماع</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- ================= TAB 3: الأحاديث النبوية ================= -->\n        <section id=\"tab-sec-hadith\" class=\"tab-panel hidden space-y-6\">\n            <!-- Filter Pills Bar -->\n            <div class=\"glass-panel rounded-3xl p-4 sm:p-6 shadow-sm border border-emerald-500/20\">\n                <div class=\"flex flex-col md:flex-row items-center justify-between gap-4\">\n                    <div class=\"flex items-center gap-2 overflow-x-auto w-full pb-2 md:pb-0\" id=\"hadith-category-pills\">\n                        <button onclick=\"filterHadiths('all')\" class=\"hadith-pill px-4 py-2 rounded-2xl text-xs sm:text-sm font-bold bg-emerald-600 text-white whitespace-nowrap shadow-sm\">\n                            الكل\n                        </button>\n                        <button onclick=\"filterHadiths('بخاري')\" class=\"hadith-pill px-4 py-2 rounded-2xl text-xs sm:text-sm font-bold bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800 whitespace-nowrap\">\n                            صحيح البخاري\n                        </button>\n                        <button onclick=\"filterHadiths('مسلم')\" class=\"hadith-pill px-4 py-2 rounded-2xl text-xs sm:text-sm font-bold bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800 whitespace-nowrap\">\n                            صحيح مسلم\n                        </button>\n                        <button onclick=\"filterHadiths('الأربعين')\" class=\"hadith-pill px-4 py-2 rounded-2xl text-xs sm:text-sm font-bold bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800 whitespace-nowrap\">\n                            الأربعين النواوية\n                        </button>\n                    </div>\n                    <div class=\"relative w-full md:w-72\">\n                        <input type=\"text\" id=\"hadith-search-input\" onkeyup=\"searchHadiths()\" placeholder=\"ابحث في الأحاديث الشريفة...\" class=\"w-full pr-10 pl-4 py-2.5 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500\">\n                        <i class=\"fa-solid fa-search absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs\"></i>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Hadith Cards Container -->\n            <div id=\"hadiths-grid\" class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n                <!-- Hadith cards injected by JS -->\n            </div>\n        </section>\n\n        <!-- ================= TAB 4: مواقيت الصلاة والقبلة ================= -->\n        <section id=\"tab-sec-prayer\" class=\"tab-panel hidden space-y-6\">\n            <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                \n                <!-- Prayer Schedule Card -->\n                <div class=\"lg:col-span-7 glass-panel rounded-3xl p-6 sm:p-8 flex flex-col justify-between shadow-xl border border-emerald-500/20\">\n                    <div>\n                        <div class=\"flex items-center justify-between mb-6\">\n                            <div>\n                                <h3 class=\"text-2xl font-black text-slate-800 dark:text-slate-100\">مواقيت الصلاة اليومية</h3>\n                                <p id=\"location-text\" class=\"text-xs font-bold text-slate-500 mt-1 flex items-center gap-1.5\">\n                                    <i class=\"fa-solid fa-location-dot text-emerald-500\"></i> المدينة: <span id=\"city-display\" class=\"text-emerald-600 dark:text-emerald-400\">القاهرة (تلقائي)</span>\n                                </p>\n                            </div>\n                            <button onclick=\"requestUserLocation()\" class=\"px-4 py-2.5 rounded-2xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-bold text-xs hover:bg-emerald-500/20 transition border border-emerald-500/20 flex items-center gap-2\">\n                                <i class=\"fa-solid fa-crosshairs\"></i> تحديد موقعي\n                            </button>\n                        </div>\n\n                        <!-- Next Prayer Countdown Banner -->\n                        <div class=\"mb-6 p-6 rounded-3xl bg-gradient-to-r from-emerald-800 via-emerald-700 to-teal-800 text-white shadow-xl flex items-center justify-between\">\n                            <div>\n                                <span class=\"text-xs font-bold uppercase tracking-wider opacity-80\">الصلاة القادمة</span>\n                                <h4 id=\"next-prayer-name\" class=\"text-3xl font-black mt-1 text-gold-400\">الفجر</h4>\n                            </div>\n                            <div class=\"text-left\">\n                                <div id=\"next-prayer-countdown\" class=\"text-3xl font-mono font-black\">--:--:--</div>\n                                <span id=\"next-prayer-time-val\" class=\"text-xs opacity-90 block mt-1 font-bold\">الموعد: --:--</span>\n                            </div>\n                        </div>\n\n                        <!-- Prayer Cards Grid -->\n                        <div id=\"prayer-cards-grid\" class=\"grid grid-cols-2 sm:grid-cols-3 gap-3\">\n                            <!-- Prayer times populated via JS -->\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Qibla Direction Compass Card -->\n                <div class=\"lg:col-span-5 glass-panel rounded-3xl p-6 sm:p-8 flex flex-col items-center justify-center text-center shadow-xl border border-emerald-500/20\">\n                    <h3 class=\"text-2xl font-black mb-1\">اتجاه القبلة الشريفة</h3>\n                    <p class=\"text-xs text-slate-500 font-bold mb-6\">مكة المكرمة - الكعبة المشرفة (21.4225° N)</p>\n\n                    <!-- Compass Visual -->\n                    <div class=\"relative w-64 h-64 sm:w-72 sm:h-72 rounded-full border-4 border-slate-200 dark:border-slate-800 flex items-center justify-center bg-slate-100/60 dark:bg-slate-900/60 shadow-inner\">\n                        <span class=\"absolute top-3 font-bold text-xs text-red-500\">شمال</span>\n                        <span class=\"absolute left-3 font-bold text-xs text-slate-400\">شرق</span>\n                        <span class=\"absolute bottom-3 font-bold text-xs text-slate-400\">جنوب</span>\n                        <span class=\"absolute right-3 font-bold text-xs text-slate-400\">غرب</span>\n\n                        <!-- Rotating Needle -->\n                        <div id=\"qibla-compass-needle\" class=\"w-full h-full absolute top-0 left-0 flex items-center justify-center transition-transform duration-500\">\n                            <div class=\"flex flex-col items-center justify-between h-full py-7\">\n                                <div class=\"flex flex-col items-center text-emerald-500\">\n                                    <i class=\"fa-solid fa-kaaba text-3xl text-gold-500 mb-1\"></i>\n                                    <i class=\"fa-solid fa-caret-up text-3xl\"></i>\n                                </div>\n                                <div class=\"w-1.5 h-12 bg-slate-300 dark:bg-slate-700 rounded-full\"></div>\n                            </div>\n                        </div>\n\n                        <div class=\"w-7 h-7 rounded-full bg-emerald-500 border-4 border-white dark:border-slate-800 z-10 shadow\"></div>\n                    </div>\n\n                    <div class=\"mt-6 text-xs font-bold text-slate-500\">\n                        زاوية القبلة: <span id=\"qibla-degree-val\" class=\"text-emerald-600 dark:text-emerald-400 font-mono text-sm\">136°</span> بالنسبة للشمال\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- ================= TAB 5: السبحة الإلكترونية ================= -->\n        <section id=\"tab-sec-tasbih\" class=\"tab-panel hidden\">\n            <div class=\"max-w-xl mx-auto glass-panel rounded-3xl p-6 sm:p-10 text-center shadow-2xl border border-emerald-500/20\">\n                <!-- Supplication Select -->\n                <div class=\"mb-6\">\n                    <label class=\"block text-xs font-extrabold text-slate-500 mb-2 uppercase tracking-wider\">اختر الذكر المبارك</label>\n                    <select id=\"dhikr-selector\" onchange=\"changeDhikrType()\" class=\"w-full px-4 py-3.5 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-sm font-bold focus:outline-none focus:ring-2 focus:ring-emerald-500 text-emerald-600 dark:text-emerald-400\">\n                        <option value=\"Subhanallah\">سُبْحَانَ اللَّهِ (سبحان الله وبحمده)</option>\n                        <option value=\"Alhamdulillah\">الْحَمْدُ لِلَّهِ (حمداً كثيراً)</option>\n                        <option value=\"AllahuAkbar\">اللَّهُ أَكْبَرُ (كبيراً والحمد لله كثيراً)</option>\n                        <option value=\"Astaghfirullah\">أَسْتَغْفِرُ اللَّهَ (العظيم وأتوب إليه)</option>\n                        <option value=\"LaIlahaIllallah\">لا إِلَهَ إِلا اللَّهُ (وحده لا شريك له)</option>\n                    </select>\n                </div>\n\n                <!-- Dhikr Display -->\n                <div class=\"my-6\">\n                    <h2 id=\"tasbih-phrase-arabic\" class=\"font-quran-text text-4xl sm:text-5xl text-emerald-600 dark:text-emerald-400 mb-2 font-bold\">سُبْحَانَ اللَّهِ</h2>\n                    <p id=\"tasbih-phrase-meaning\" class=\"text-xs sm:text-sm text-slate-500 font-semibold\">تنزيه الله تعالى عن كل نقص</p>\n                </div>\n\n                <!-- Interactive Clicker Button -->\n                <div class=\"my-8 flex justify-center\">\n                    <button onclick=\"incrementTasbihCount()\" class=\"w-56 h-56 rounded-full bg-gradient-to-tr from-emerald-800 via-emerald-600 to-teal-500 text-white shadow-2xl shadow-emerald-600/40 flex flex-col items-center justify-center active:scale-95 transition transform border-8 border-white dark:border-slate-800 focus:outline-none group\">\n                        <span id=\"tasbih-counter\" class=\"text-6xl font-black font-mono tracking-tight group-hover:scale-105 transition\">0</span>\n                        <span class=\"text-xs font-bold uppercase tracking-widest mt-2 opacity-90\">اضغط للتسبيح</span>\n                    </button>\n                </div>\n\n                <!-- Target & Reset controls -->\n                <div class=\"flex items-center justify-between text-sm pt-5 border-t border-slate-200 dark:border-slate-800/80\">\n                    <div class=\"text-right\">\n                        <span class=\"text-xs font-bold text-slate-500\">الهدف: <strong id=\"tasbih-target-val\" class=\"text-emerald-500\">33</strong></span>\n                        <div class=\"w-28 h-2 bg-slate-200 dark:bg-slate-800 rounded-full mt-1.5 overflow-hidden\">\n                            <div id=\"tasbih-progress-bar\" class=\"h-full bg-emerald-500 w-0 transition-all duration-300\"></div>\n                        </div>\n                    </div>\n                    <button onclick=\"resetTasbihCount()\" class=\"px-4 py-2.5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 font-bold text-xs hover:bg-red-500 hover:text-white transition flex items-center gap-2\">\n                        <i class=\"fa-solid fa-rotate-right\"></i> تصفير العداد\n                    </button>\n                </div>\n            </div>\n        </section>\n\n    </main>\n\n    <!-- HIDDEN GLOBAL AUDIO PLAYER -->\n    <audio id=\"global-quran-audio\" class=\"hidden\"></audio>\n\n    <!-- GLOBAL AUDIO PLAYER BAR -->\n    <div id=\"sticky-audio-bar\" class=\"fixed bottom-0 left-0 right-0 glass-panel border-t border-slate-200 dark:border-slate-800 px-4 py-3 z-40 transform translate-y-full transition-transform duration-300\">\n        <div class=\"max-w-7xl mx-auto flex items-center justify-between gap-4\">\n            <div class=\"flex items-center gap-3\">\n                <div class=\"w-10 h-10 rounded-2xl bg-emerald-500/20 text-emerald-500 flex items-center justify-center font-bold\">\n                    <i class=\"fa-solid fa-music\"></i>\n                </div>\n                <div>\n                    <h5 id=\"player-title\" class=\"text-xs font-bold text-slate-800 dark:text-slate-200\">تلاوة عذبة</h5>\n                    <p id=\"player-subtitle\" class=\"text-[11px] text-slate-500\">القارئ: مشاري العفاسي</p>\n                </div>\n            </div>\n            <div class=\"flex items-center gap-3\">\n                <button onclick=\"toggleAudioPlayback()\" id=\"audio-play-toggle-btn\" class=\"w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center hover:bg-emerald-700 transition shadow\">\n                    <i class=\"fa-solid fa-play text-sm\"></i>\n                </button>\n                <button onclick=\"closeAudioPlayerBar()\" class=\"text-slate-400 hover:text-slate-600 p-2\">\n                    <i class=\"fa-solid fa-xmark text-lg\"></i>\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- JAVASCRIPT LOGIC BLOCK -->\n    <script>\n        /* ================= STATE MANAGEMENT ================= */\n        const appState = {\n            activeTab: 'moshaf',\n            moshaf: {\n                currentPage: parseInt(localStorage.getItem('nur_moshaf_last_page') || '1'),\n                isDualView: false,\n                isServerOnline: true,\n                cdnIndex: 0\n            },\n            quran: {\n                surahs: [],\n                activeSurah: null,\n                reciter: 'ar.alafasy'\n            },\n            tasbih: {\n                count: 0,\n                target: 33,\n                type: 'Subhanallah'\n            }\n        };\n\n        // Reliable Primary & Fallback CDNs for High-Definition Quran Pages\n        const MOSHAF_SERVERS = [\n            (page) => `https://quran.ksu.edu.eg/png_big/${page}.png`,\n            (page) => `https://everyayah.com/data/quranimages/${page}.png`,\n            (page) => `https://madani.quran.ws/svg/${page}.svg`\n        ];\n\n        // Static Hadith Dataset for instant local searching\n        const HADITH_DATASET = [\n            {\n                id: 1,\n                category: 'بخاري',\n                text: 'إنَّما الأَعْمالُ بالنِّيَّاتِ، وإنَّما لِكُلِّ امْرِئٍ ما نَوَى، فمَن كانَتْ هِجْرَتُهُ إلى دُنْيا يُصِيبُها، أوْ إلى امْرَأَةٍ يَنْكِحُها، فَهِجْرَتُهُ إلى ما هاجَرَ إلَيْهِ.',\n                narrator: 'عمر بن الخطاب رضي الله عنه',\n                source: 'صحيح البخاري - رقم ١'\n            },\n            {\n                id: 2,\n                category: 'مسلم',\n                text: 'المُسْلِمُ مَنْ سَلِمَ المُنْهَجونَ والعامَّةُ مِنْ لِسَانِهِ وَيَدِهِ، والمُؤْمِنُ مَنْ أَمِنَهُ النَّاسُ عَلَى دِمَائِهِمْ وَأَمْوَالِهِمْ.',\n                narrator: 'عبد الله بن عمرو رضي الله عنهما',\n                source: 'صحيح مسلم - رقم ٤٠'\n            },\n            {\n                id: 3,\n                category: 'الأربعين',\n                text: 'لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.',\n                narrator: 'أنس بن مالك رضي الله عنه',\n                source: 'الأربعين النواوية - الحديث ١٣'\n            },\n            {\n                id: 4,\n                category: 'بخاري',\n                text: 'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ.',\n                narrator: 'عثمان بن عفان رضي الله عنه',\n                source: 'صحيح البخاري - رقم ٥٠٢٧'\n            },\n            {\n                id: 5,\n                category: 'الأربعين',\n                text: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ.',\n                narrator: 'أبو هريرة رضي الله عنه',\n                source: 'الأربعين النواوية - الحديث ١٥'\n            }\n        ];\n\n        const DHIKR_PRESETS = {\n            'Subhanallah': { ar: 'سُبْحَانَ اللَّهِ', meaning: 'تنزيه الله تعالى عن كل نقص وخلق' },\n            'Alhamdulillah': { ar: 'الْحَمْدُ لِلَّهِ', meaning: 'الثناء الكامل لله عز وجل على نِعَمه' },\n            'AllahuAkbar': { ar: 'اللَّهُ أَكْبَرُ', meaning: 'الله أعظم وأكبر من كل شيء' },\n            'Astaghfirullah': { ar: 'أَسْتَغْفِرُ اللَّهَ', meaning: 'طلب المغفرة والصفح من الله تعالى' },\n            'LaIlahaIllallah': { ar: 'لا إِلَهَ إِلا اللَّهُ', meaning: 'شهادة التوحيد والإخلاص لله' }\n        };\n\n        /* ================= APP LIFECYCLE INIT ================= */\n        window.onload = function() {\n            initTheme();\n            checkServerConnectivity();\n            fetchSurahDirectory();\n            initMoshafModule();\n            renderHadithList(HADITH_DATASET);\n            initPrayerTimes();\n        };\n\n        /* ================= TAB SWITCHING LOGIC (FIXED & GUARANTEED) ================= */\n        function switchTab(tabId) {\n            // Hide all tab panels\n            document.querySelectorAll('.tab-panel').forEach(panel => {\n                panel.classList.add('hidden');\n                panel.classList.remove('block');\n            });\n\n            // Reset Desktop Buttons\n            document.querySelectorAll('.nav-tab').forEach(btn => {\n                btn.classList.remove('bg-white', 'dark:bg-slate-800', 'text-emerald-600', 'dark:text-emerald-400', 'shadow-sm');\n                btn.classList.add('text-slate-600', 'dark:text-slate-300');\n            });\n\n            // Reset Mobile Buttons\n            document.querySelectorAll('.mob-tab').forEach(btn => {\n                btn.classList.remove('text-emerald-500');\n                btn.classList.add('text-slate-400');\n            });\n\n            // Show Active Panel\n            const activePanel = document.getElementById(`tab-sec-${tabId}`);\n            if (activePanel) {\n                activePanel.classList.remove('hidden');\n                activePanel.classList.add('block');\n            }\n\n            // Highlight Desktop Button\n            const activeNavBtn = document.getElementById(`nav-btn-${tabId}`);\n            if (activeNavBtn) {\n                activeNavBtn.classList.add('bg-white', 'dark:bg-slate-800', 'text-emerald-600', 'dark:text-emerald-400', 'shadow-sm');\n                activeNavBtn.classList.remove('text-slate-600', 'dark:text-slate-300');\n            }\n\n            // Highlight Mobile Button\n            const activeMobBtn = document.getElementById(`mob-btn-${tabId}`);\n            if (activeMobBtn) {\n                activeMobBtn.classList.add('text-emerald-500');\n                activeMobBtn.classList.remove('text-slate-400');\n            }\n\n            appState.activeTab = tabId;\n        }\n\n        /* ================= THEME TOGGLE ================= */\n        function initTheme() {\n            if (localStorage.theme === 'light') {\n                document.documentElement.classList.remove('dark');\n            } else {\n                document.documentElement.classList.add('dark');\n            }\n        }\n\n        function toggleTheme() {\n            if (document.documentElement.classList.contains('dark')) {\n                document.documentElement.classList.remove('dark');\n                localStorage.theme = 'light';\n            } else {\n                document.documentElement.classList.add('dark');\n                localStorage.theme = 'dark';\n            }\n        }\n\n        /* ================= SERVER CONNECTION CHECKER ================= */\n        function checkServerConnectivity() {\n            const statusDot = document.getElementById('status-dot');\n            const statusPing = document.getElementById('status-ping');\n            const statusText = document.getElementById('status-text');\n\n            // Quick image ping test to confirm CDN is active\n            const testImg = new Image();\n            testImg.onload = function() {\n                appState.moshaf.isServerOnline = true;\n                statusDot.className = \"relative inline-flex rounded-full h-3 w-3 bg-emerald-500\";\n                statusPing.className = \"animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75\";\n                statusText.innerText = \"متصل بسيرفرات مصحف المجمع الملكي فهد (عالية الجودة)\";\n            };\n            testImg.onerror = function() {\n                // Switch to fallback CDN automatically\n                appState.moshaf.cdnIndex = (appState.moshaf.cdnIndex + 1) % MOSHAF_SERVERS.length;\n                statusText.innerText = \"تم التبديل تلقائياً لسيرفر الاحتياط السريع\";\n            };\n            testImg.src = MOSHAF_SERVERS[appState.moshaf.cdnIndex](1);\n        }\n\n        /* ================= REAL MOSHAF MODULE LOGIC ================= */\n        function initMoshafModule() {\n            // Check if saved page exists\n            const savedPage = localStorage.getItem('nur_moshaf_last_page');\n            if (savedPage && parseInt(savedPage) > 1) {\n                document.getElementById('resume-bookmark-banner').classList.remove('hidden');\n                document.getElementById('saved-page-num').innerText = savedPage;\n            }\n\n            // Populate Juz Dropdown (1 to 30)\n            const juzSelect = document.getElementById('moshaf-juz-select');\n            juzSelect.innerHTML = `<option value=\"\">اختر الجزء (١-٣٠)...</option>`;\n            for (let j = 1; j <= 30; j++) {\n                juzSelect.innerHTML += `<option value=\"${j}\">الجزء ${j}</option>`;\n            }\n\n            // Setup Touch Swipe Gestures\n            setupTouchSwipe();\n\n            // Render current page\n            renderMoshafPage(appState.moshaf.currentPage);\n        }\n\n        function renderMoshafPage(pageNum) {\n            pageNum = Math.max(1, Math.min(604, parseInt(pageNum)));\n            appState.moshaf.currentPage = pageNum;\n\n            // Sync controls\n            document.getElementById('moshaf-page-input').value = pageNum;\n            document.getElementById('moshaf-slider').value = pageNum;\n            document.getElementById('moshaf-page-display').innerText = `صفحة ${pageNum}`;\n\n            const imgRight = document.getElementById('moshaf-img-right');\n            const imgLeft = document.getElementById('moshaf-img-left');\n            const loader = document.getElementById('moshaf-loader');\n\n            loader.classList.remove('hidden');\n\n            const currentCDN = MOSHAF_SERVERS[appState.moshaf.cdnIndex];\n\n            if (appState.moshaf.isDualView && pageNum < 604) {\n                document.getElementById('moshaf-img-container-left').classList.remove('hidden');\n                document.getElementById('moshaf-img-container-right').classList.replace('w-full', 'w-1/2');\n\n                imgRight.src = currentCDN(pageNum);\n                imgLeft.src = currentCDN(pageNum + 1);\n\n                imgRight.onload = () => loader.classList.add('hidden');\n            } else {\n                document.getElementById('moshaf-img-container-left').classList.add('hidden');\n                document.getElementById('moshaf-img-container-right').classList.replace('w-1/2', 'w-full');\n\n                imgRight.src = currentCDN(pageNum);\n                imgRight.onload = () => loader.classList.add('hidden');\n            }\n\n            // Handle image load error fallback\n            imgRight.onerror = function() {\n                appState.moshaf.cdnIndex = (appState.moshaf.cdnIndex + 1) % MOSHAF_SERVERS.length;\n                imgRight.src = MOSHAF_SERVERS[appState.moshaf.cdnIndex](pageNum);\n            };\n\n            updateMoshafMetaDetails(pageNum);\n        }\n\n        function prevMoshafPage() {\n            // In RTL Arabic reading order, Previous Page means pageNum - 1\n            const step = appState.moshaf.isDualView ? 2 : 1;\n            if (appState.moshaf.currentPage - step >= 1) {\n                renderMoshafPage(appState.moshaf.currentPage - step);\n            }\n        }\n\n        function nextMoshafPage() {\n            // In RTL Arabic reading order, Next Page means pageNum + 1\n            const step = appState.moshaf.isDualView ? 2 : 1;\n            if (appState.moshaf.currentPage + step <= 604) {\n                renderMoshafPage(appState.moshaf.currentPage + step);\n            }\n        }\n\n        function jumpToPage(page) {\n            if (page) renderMoshafPage(page);\n        }\n\n        function jumpToJuz(juzNum) {\n            if (!juzNum) return;\n            // Standard Quran Juz Start Pages\n            const juzPages = [1, 22, 42, 62, 82, 102, 122, 142, 162, 182, 202, 222, 242, 262, 282, 302, 322, 342, 362, 382, 402, 422, 442, 462, 482, 502, 522, 542, 562, 582];\n            renderMoshafPage(juzPages[parseInt(juzNum) - 1] || 1);\n        }\n\n        function jumpToSurah(surahNum) {\n            if (!surahNum) return;\n            const surah = appState.quran.surahs.find(s => s.number == surahNum);\n            if (surah && surah.startPage) {\n                renderMoshafPage(surah.startPage);\n            } else {\n                // Fallback page estimate\n                const pageEst = Math.min(604, Math.floor((surahNum - 1) * 5.2) + 1);\n                renderMoshafPage(pageEst);\n            }\n        }\n\n        function updateMoshafMetaDetails(pageNum) {\n            const juzApprox = Math.min(30, Math.floor((pageNum - 1) / 20.1) + 1);\n            document.getElementById('moshaf-juz-title').innerText = `الجزء ${juzApprox}`;\n\n            if (appState.quran.surahs.length > 0) {\n                const surah = appState.quran.surahs.find(s => pageNum >= s.startPage && pageNum <= (s.endPage || s.startPage + 10));\n                if (surah) {\n                    document.getElementById('moshaf-surah-title').innerHTML = `<i class=\"fa-solid fa-kaaba\"></i> سورة ${surah.name}`;\n                }\n            }\n        }\n\n        function toggleDualPageView() {\n            appState.moshaf.isDualView = !appState.moshaf.isDualView;\n            document.getElementById('dual-mode-text').innerText = appState.moshaf.isDualView ? 'عرض صفحة واحدة' : 'عرض صفحتين';\n            renderMoshafPage(appState.moshaf.currentPage);\n        }\n\n        function saveMoshafBookmark() {\n            localStorage.setItem('nur_moshaf_last_page', appState.moshaf.currentPage);\n            alert(`تم حفظ الصفحة ${appState.moshaf.currentPage} كعلامة مرجعية لموضع قراءتك!`);\n        }\n\n        function loadSavedBookmarkPage() {\n            const saved = localStorage.getItem('nur_moshaf_last_page');\n            if (saved) {\n                renderMoshafPage(saved);\n                document.getElementById('resume-bookmark-banner').classList.add('hidden');\n            }\n        }\n\n        function toggleStageFullscreen() {\n            const stage = document.getElementById('moshaf-stage');\n            if (!document.fullscreenElement) {\n                stage.requestFullscreen().catch(() => alert('تعذر تفعيل ملء الشاشة'));\n            } else {\n                document.exitFullscreen();\n            }\n        }\n\n        function playCurrentPageAudio() {\n            playAudioVerse(1, appState.moshaf.currentPage);\n        }\n\n        function setupTouchSwipe() {\n            const wrapper = document.getElementById('moshaf-images-wrapper');\n            let touchStartX = 0;\n\n            wrapper.addEventListener('touchstart', e => {\n                touchStartX = e.changedTouches[0].screenX;\n            }, { passive: true });\n\n            wrapper.addEventListener('touchend', e => {\n                const touchEndX = e.changedTouches[0].screenX;\n                if (touchStartX - touchEndX > 50) {\n                    prevMoshafPage(); // Swipe Left in RTL -> Previous Page\n                } else if (touchEndX - touchStartX > 50) {\n                    nextMoshafPage(); // Swipe Right in RTL -> Next Page\n                }\n            }, { passive: true });\n        }\n\n        /* ================= QURAN & SURAH EXPLORER ================= */\n        async function fetchSurahDirectory() {\n            try {\n                const res = await fetch('https://api.alquran.cloud/v1/surah');\n                const data = await res.json();\n                \n                // Mapped starting page references for surahs\n                appState.quran.surahs = data.data.map((s, idx) => ({\n                    ...s,\n                    startPage: Math.min(604, Math.floor(idx * 5.25) + 1)\n                }));\n\n                renderSurahSidebar(appState.quran.surahs);\n                populateMoshafSurahDropdown(appState.quran.surahs);\n            } catch (e) {\n                console.error(\"Error fetching surahs\", e);\n            }\n        }\n\n        function renderSurahSidebar(surahs) {\n            const sidebar = document.getElementById('surah-list-sidebar');\n            sidebar.innerHTML = surahs.map(s => `\n                <div onclick=\"loadSurahVerses(${s.number})\" class=\"p-3.5 rounded-2xl hover:bg-slate-100 dark:hover:bg-slate-800/80 cursor-pointer flex items-center justify-between transition border border-transparent hover:border-emerald-500/20\">\n                    <div class=\"flex items-center gap-3\">\n                        <span class=\"w-8 h-8 rounded-xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-extrabold text-xs flex items-center justify-center border border-emerald-500/20\">\n                            ${s.number}\n                        </span>\n                        <div>\n                            <h4 class=\"text-sm font-bold\">${s.name}</h4>\n                            <p class=\"text-[11px] text-slate-400 font-medium\">${s.revelationType === 'Meccan' ? 'مكية' : 'مدنية'} • ${s.numberOfAyahs} آية</p>\n                        </div>\n                    </div>\n                    <i class=\"fa-solid fa-chevron-left text-xs text-slate-400\"></i>\n                </div>\n            `).join('');\n        }\n\n        function populateMoshafSurahDropdown(surahs) {\n            const dropdown = document.getElementById('moshaf-surah-select');\n            dropdown.innerHTML = `<option value=\"\">اختر السورة...</option>` + surahs.map(s => `\n                <option value=\"${s.number}\">${s.number}. سورة ${s.name}</option>\n            `).join('');\n        }\n\n        function filterSurahsList() {\n            const query = document.getElementById('surah-search-input').value.trim();\n            const filtered = appState.quran.surahs.filter(s => \n                s.name.includes(query) || s.number.toString() === query\n            );\n            renderSurahSidebar(filtered);\n        }\n\n        async function loadSurahVerses(surahNum) {\n            const container = document.getElementById('verses-list-container');\n            container.innerHTML = `\n                <div class=\"text-center py-16 text-slate-400\">\n                    <div class=\"w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto mb-2\"></div>\n                    <p class=\"text-xs font-bold\">جاري تحميل آيات السورة...</p>\n                </div>\n            `;\n\n            try {\n                const res = await fetch(`https://api.alquran.cloud/v1/surah/${surahNum}/editions/quran-uthmani,ar.alafasy`);\n                const data = await res.json();\n                \n                const arabicData = data.data[0];\n                appState.quran.activeSurah = arabicData;\n\n                // Update Header\n                document.getElementById('active-surah-header').classList.remove('hidden');\n                document.getElementById('active-surah-ar-name').innerText = `سورة ${arabicData.name}`;\n                document.getElementById('active-surah-sub').innerText = `${arabicData.revelationType === 'Meccan' ? 'مكية' : 'مدنية'} • عدد آياتها ${arabicData.numberOfAyahs}`;\n\n                // Render Verses\n                container.innerHTML = arabicData.ayahs.map(ayah => `\n                    <div id=\"verse-box-${ayah.numberInSurah}\" class=\"p-5 rounded-2xl glass-card border border-slate-200 dark:border-slate-800 transition hover:border-emerald-500/30\">\n                        <div class=\"flex items-center justify-between mb-3 text-xs text-slate-400 font-bold border-b border-slate-200 dark:border-slate-800/60 pb-2\">\n                            <span class=\"bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 px-3 py-1 rounded-full\">الآية ${ayah.numberInSurah}</span>\n                            <div class=\"flex items-center gap-2\">\n                                <button onclick=\"playAudioVerse(${surahNum}, ${ayah.numberInSurah})\" class=\"hover:text-emerald-500 transition\"><i class=\"fa-solid fa-volume-high\"></i> استماع</button>\n                                <span>•</span>\n                                <button onclick=\"copyVerseText('${ayah.text}')\" class=\"hover:text-emerald-500 transition\"><i class=\"fa-regular fa-copy\"></i> نسخ</button>\n                            </div>\n                        </div>\n                        <p class=\"font-quran-text text-2xl sm:text-3xl text-right leading-loose text-slate-900 dark:text-slate-100\">${ayah.text}</p>\n                    </div>\n                `).join('');\n            } catch (e) {\n                container.innerHTML = `<p class=\"text-red-500 text-xs text-center py-8\">حدث خطأ أثناء تحميل الآيات. يرجى التحقق من الاتصال.</p>`;\n            }\n        }\n\n        /* ================= HADITH MODULE ================= */\n        function renderHadithList(list) {\n            const grid = document.getElementById('hadiths-grid');\n            grid.innerHTML = list.map(h => `\n                <div class=\"glass-panel rounded-3xl p-6 flex flex-col justify-between shadow-lg border border-gold-500/20\">\n                    <div>\n                        <div class=\"flex items-center justify-between mb-4\">\n                            <span class=\"px-3 py-1 rounded-full text-xs font-bold bg-gold-500/10 text-gold-600 dark:text-gold-400 border border-gold-500/20\">\n                                ${h.source}\n                            </span>\n                            <button onclick=\"copyVerseText('${h.text}')\" class=\"text-slate-400 hover:text-emerald-500 text-xs font-bold\"><i class=\"fa-regular fa-copy\"></i> نسخ الحديث</button>\n                        </div>\n                        <p class=\"font-amiri text-lg sm:text-xl text-slate-800 dark:text-slate-100 leading-relaxed font-bold mb-4\">\"${h.text}\"</p>\n                    </div>\n                    <div class=\"pt-3 border-t border-slate-200 dark:border-slate-800/80 text-xs text-slate-400 font-bold flex items-center justify-between\">\n                        <span>الراوي: ${h.narrator}</span>\n                        <i class=\"fa-solid fa-scroll text-gold-500\"></i>\n                    </div>\n                </div>\n            `).join('');\n        }\n\n        function filterHadiths(category) {\n            // Update Pills UI\n            document.querySelectorAll('.hadith-pill').forEach(btn => {\n                btn.className = \"hadith-pill px-4 py-2 rounded-2xl text-xs sm:text-sm font-bold bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800 whitespace-nowrap\";\n            });\n            event.currentTarget.className = \"hadith-pill px-4 py-2 rounded-2xl text-xs sm:text-sm font-bold bg-emerald-600 text-white whitespace-nowrap shadow-sm\";\n\n            if (category === 'all') {\n                renderHadithList(HADITH_DATASET);\n            } else {\n                const filtered = HADITH_DATASET.filter(h => h.category === category || h.source.includes(category));\n                renderHadithList(filtered);\n            }\n        }\n\n        function searchHadiths() {\n            const query = document.getElementById('hadith-search-input').value.trim();\n            const filtered = HADITH_DATASET.filter(h => h.text.includes(query) || h.narrator.includes(query));\n            renderHadithList(filtered);\n        }\n\n        /* ================= PRAYER TIMES & QIBLA ================= */\n        async function initPrayerTimes(lat = 30.0444, lng = 31.2357, cityName = \"القاهرة\") {\n            try {\n                const res = await fetch(`https://api.aladhan.com/v1/timings?latitude=${lat}&longitude=${lng}&method=5`);\n                const data = await res.json();\n                const timings = data.data.timings;\n\n                document.getElementById('city-display').innerText = cityName;\n\n                const prayerNames = {\n                    Fajr: 'الفجر',\n                    Sunrise: 'الشروق',\n                    Dhuhr: 'الظهر',\n                    Asr: 'العصر',\n                    Maghrib: 'المغرب',\n                    Isha: 'العشاء'\n                };\n\n                const grid = document.getElementById('prayer-cards-grid');\n                grid.innerHTML = Object.keys(prayerNames).map(key => `\n                    <div class=\"p-4 rounded-2xl glass-card border border-slate-200 dark:border-slate-800 text-center\">\n                        <span class=\"text-xs font-bold text-slate-400 block mb-1\">${prayerNames[key]}</span>\n                        <span class=\"text-lg font-black text-emerald-600 dark:text-emerald-400 font-mono\">${timings[key]}</span>\n                    </div>\n                `).join('');\n\n                // Next Prayer logic\n                document.getElementById('next-prayer-name').innerText = 'الفجر';\n                document.getElementById('next-prayer-time-val').innerText = `الموعد: ${timings['Fajr']}`;\n                document.getElementById('next-prayer-countdown').innerText = timings['Fajr'];\n\n                // Qibla calculation\n                calculateQiblaDirection(lat, lng);\n            } catch (e) {\n                console.error(\"Prayer API error\", e);\n            }\n        }\n\n        function requestUserLocation() {\n            if (navigator.geolocation) {\n                navigator.geolocation.getCurrentPosition(pos => {\n                    initPrayerTimes(pos.coords.latitude, pos.coords.longitude, \"موقعك الحالي\");\n                }, () => {\n                    alert('تعذر الوصول لموقعك الحالي، تم استخدام التوقيت الافتراضي (القاهرة)');\n                });\n            }\n        }\n\n        function calculateQiblaDirection(lat, lng) {\n            const meccaLat = 21.4225 * Math.PI / 180;\n            const meccaLng = 39.8262 * Math.PI / 180;\n            const userLat = lat * Math.PI / 180;\n            const userLng = lng * Math.PI / 180;\n\n            const y = Math.sin(meccaLng - userLng);\n            const x = Math.cos(userLat) * Math.tan(meccaLat) - Math.sin(userLat) * Math.cos(meccaLng - userLng);\n            let qiblaRad = Math.atan2(y, x);\n            let qiblaDeg = qiblaRad * 180 / Math.PI;\n            if (qiblaDeg < 0) qiblaDeg += 360;\n\n            document.getElementById('qibla-degree-val').innerText = `${Math.round(qiblaDeg)}°`;\n            document.getElementById('qibla-compass-needle').style.transform = `rotate(${qiblaDeg}deg)`;\n        }\n\n        /* ================= DIGITAL TASBIH COUNTER ================= */\n        function incrementTasbihCount() {\n            appState.tasbih.count++;\n            document.getElementById('tasbih-counter').innerText = appState.tasbih.count;\n\n            if (navigator.vibrate) navigator.vibrate(35);\n\n            const pct = Math.min((appState.tasbih.count / appState.tasbih.target) * 100, 100);\n            document.getElementById('tasbih-progress-bar').style.width = `${pct}%`;\n        }\n\n        function resetTasbihCount() {\n            appState.tasbih.count = 0;\n            document.getElementById('tasbih-counter').innerText = 0;\n            document.getElementById('tasbih-progress-bar').style.width = '0%';\n        }\n\n        function changeDhikrType() {\n            const val = document.getElementById('dhikr-selector').value;\n            const preset = DHIKR_PRESETS[val];\n            document.getElementById('tasbih-phrase-arabic').innerText = preset.ar;\n            document.getElementById('tasbih-phrase-meaning').innerText = preset.meaning;\n            resetTasbihCount();\n        }\n\n        /* ================= AUDIO PLAYER CONTROLLER ================= */\n        function playAudioVerse(surahNum, verseNum) {\n            const paddedSurah = String(surahNum).padStart(3, '0');\n            const paddedVerse = String(verseNum).padStart(3, '0');\n            const audioUrl = `https://everyayah.com/data/Alafasy_128kbps/${paddedSurah}${paddedVerse}.mp3`;\n\n            const audio = document.getElementById('global-quran-audio');\n            audio.src = audioUrl;\n            audio.play();\n\n            document.getElementById('sticky-audio-bar').classList.remove('translate-y-full');\n            document.getElementById('player-title').innerText = `سورة ${surahNum} - آية ${verseNum}`;\n            document.getElementById('audio-play-toggle-btn').innerHTML = `<i class=\"fa-solid fa-pause text-sm\"></i>`;\n        }\n\n        function toggleAudioPlayback() {\n            const audio = document.getElementById('global-quran-audio');\n            const btn = document.getElementById('audio-play-toggle-btn');\n            if (audio.paused) {\n                audio.play();\n                btn.innerHTML = `<i class=\"fa-solid fa-pause text-sm\"></i>`;\n            } else {\n                audio.pause();\n                btn.innerHTML = `<i class=\"fa-solid fa-play text-sm\"></i>`;\n            }\n        }\n\n        function closeAudioPlayerBar() {\n            const audio = document.getElementById('global-quran-audio');\n            audio.pause();\n            document.getElementById('sticky-audio-bar').classList.add('translate-y-full');\n        }\n\n        /* ================= UTILITY FUNCTIONS ================= */\n        function copyVerseText(text) {\n            const temp = document.createElement('textarea');\n            temp.value = text;\n            document.body.appendChild(temp);\n            temp.select();\n            document.execCommand('copy');\n            document.body.removeChild(temp);\n            alert('تم نسخ النص بنجاح إلى الحافظة!');\n        }\n    </script>\n</body>\n</html>";

/* The behaviour travels in starters/nur-runtime.js, not here. Kept as an
   export so a consumer that imports only this module still has the name. */
export const NUR_RUNTIME_JS = '';
